    "attendance.noReading": "The design prints a sentence under this chart \u2014 \u201cthree weeks at zero, and the drop starts the week after his last PT session\u201d. Nothing here produces one: relating a gap to a cause needs a module that reasons about it, and a plausible sentence written by the page would be a confident answer with nothing behind it.",
    "attendance.credentialNote": "A visit names the club, the local time and how they got in. Never the credential itself: the stored value is a one-way digest, and a listing carrying it would let anybody holding a candidate card confirm whose it is.",
