    "dispute.ev.attendance": "Check-ins in the billed period",
    "dispute.ev.contract": "Signed membership contract",
    "dispute.ev.invoice": "Invoice and its fiscal acknowledgement",
    "dispute.ev.statement": "Written statement",
    "dispute.ev.noPeriod": "This payment cites no invoice, so there is no billed period to count over \u2014 which is a different answer from the member not having come.",
    "dispute.ev.attendanceRefused": "Counting check-ins needs `access.decision.read`, which this session does not hold. The gym may well be able to prove this.",
    "dispute.ev.noMembership": "The invoice cites no membership, so there is no agreement to produce.",
    "dispute.ev.contractRefused": "Reading the agreement needs `membership.record.read`, which this session does not hold.",
    "dispute.ev.unsigned": "The agreement exists and was never signed, which is the one piece of this a scheme would ask about.",
    "dispute.ev.noInvoice": "The payment is not against an invoice, so there is no document number to cite.",
    "dispute.ev.filingRejected": "The document is held, and its fiscal filing was rejected \u2014 so there is no acknowledgement reference to cite beside it.",
    "dispute.ev.notFiled": "The document is held and has not been fiscally acknowledged, so only the invoice itself can be cited.",
    "dispute.ev.statementIsYours": "Yours to write. Nothing in this build holds one, and the command that answers a dispute takes a locator rather than the text.",
    "dispute.strongestEvidence": "**The check-in record is the strongest evidence a gym has**, and it is the only line here Veyro assembles rather than quotes: it is counted from door entries and never from access decisions, because a card failing at the door produces refused decisions for exactly the member whose attendance is being proved. Each visit is dated in the timezone of the club whose door it was, which is what \u201cthe billed month\u201d means to whoever reads the case.",
    "dispute.status.open": "Disputed",
    "dispute.status.responded": "Answered, awaiting the scheme",
    "dispute.status.won": "Won",
    "dispute.status.lost": "Lost",
    "dispute.status.withdrawn": "Withdrawn",
    "dispute.kind.chargeback": "chargeback",
    "dispute.kind.retrieval": "retrieval request",
    "dispute.kind.preArbitration": "pre-arbitration",
    "dispute.reason.notReceived": "They are claiming the service was not received.",
    "dispute.reason.unacceptable": "They are claiming the service was not as described.",
    "dispute.reason.fraudulent": "They are claiming the card was used fraudulently.",
    "dispute.reason.duplicate": "They are claiming they were charged twice.",
    "dispute.reason.cancelled": "They are claiming the membership had been cancelled.",
    "dispute.reason.creditNotProcessed": "They are claiming a refund was promised and never paid.",
    "dispute.reason.unrecognised": "They did not recognise the charge.",
    "dispute.notYet": "What this screen cannot do",
    "dispute.submitTitle": "Submit the evidence",
    "dispute.submitWhy": "Nothing in this build sends anything to a scheme. `respond_to_dispute` records that a named actor sent evidence and takes a locator rather than the evidence itself \u2014 a row saying the case was answered, written by nothing that answered it, is the fabricated-evidence shape this codebase has been bitten by. It is a stepped-up financial write with no form here.",
    "dispute.acceptTitle": "Accept the loss",
    "dispute.acceptWhy": "The canvas is right that this is a real option and a decision rather than a lapse, which is an argument for recording who made it. `settle_dispute` does that and is stepped-up financial, with no form in this build \u2014 and a button that answered 403 would be worse than its absence on the one action nobody can undo.",
    "dispute.heldTitle": "The money",
    "dispute.heldWhy": "A chargeback holds the amount at the provider until the scheme decides. Nothing here moves it: a lost chargeback is reconciled against the provider statement rather than reversed in the ledger, so this screen shows exposure and never a posting.",
