    "perms.moduleLegendNote": "يلخّص صفّ الوحدة كل قدرة فيها، لأن 205 صفوف قائمة لا مقارنة. و◑ هي الأكثر ورودًا والأهم: الدور يستطيع بعض ما تغطيه هذه الوحدة، ولا تقول أيَّها إلا القائمة الكاملة.",
    "perms.noCatalog": "تعذّرت قراءة فهرس الصلاحيات، فلا مصفوفة تُرسم. ومن دونه تكون الشبكة أسماء صلاحيات مجرّدة لا تقول للقارئ شيئاً يتصرّف بناءً عليه.",
    "perms.mark.yes": "يستطيع",
    "perms.mark.stepUp": "يملكها، لكنها تحتاج تسجيل دخول أقوى",
    "perms.mark.unreachable": "يملكها، ولا أحد في هذا البناء يستطيع استخدامها",
    "perms.mark.no": "غير متاحة، وغائبة عن واجهته تماماً",
    "perms.legendNote": "العلامة الوسطى في التصميم هي «يستطيع طلب الموافقة». وفي MOD-008 الموافقات مسار عمل لا صفة لكل دور — فطلبها يحتاج صلاحية الفعل نفسه — لذا الموضع الأوسط هنا هو الحالة التي يملكها هذا البناء فعلاً: الدور يملك الصلاحية ولا يستطيع تسجيل دخول عادي استخدامها. والعلامة الرابعة للمستوى الثالث الذي يحتاج مُصادِقاً عتادياً لا يستطيع MOD-007 التحقق منه، فصلاحية الدعم الطارئة وتصرّف الذكاء الاصطناعي نيابة عن عضو يملكهما من لا يستطيع استخدامهما.",
    "perms.roles": "الأدوار",
    "perms.noRoles": "لا أدوار بعد. المستأجر غير قابل للاستخدام حتى يُنشئ أحدهم الدور الأول، وهو نداء واحد يرفض بمجرد وجود أي إسناد.",
    "perms.builtin": "مُعرَّف من المنتج",
    "perms.tenantDefined": "مُعرَّف من هذا المستأجر",
    "perms.held": "الصلاحيات المملوكة",
    "perms.mine": "ما تستطيع هذه الجلسة فعله",
    "perms.mineLead": "من قواعد المُقيِّم نفسه، ضمن النطاق الذي اشتقّه الخادم. الصلاحية المذكورة هنا تُرفض مع ذلك إذا احتاج الإجراء تسجيل دخول أقوى مما تملكه هذه الجلسة.",
    "perms.scope": "النطاق",
    "perms.audit": "سجل التدقيق",
    "perms.auditLead": "سجل مسلسل بالتجزئة لكل رفض تقوم به البوابة، وللأفعال التي تمنح الوصول: إنشاء دور، ومنح دور، والبتّ في موافقة. أما الإجراء المسموح العادي فلا يُسجَّل عمداً — لا يوجد هنا صف يقول إن أحدهم قرأ ملف عضو.",
    "perms.noAudit": "لا شيء مُسجَّل بعد.",
    "perms.chainOk": "السلسلة متحققة عبر كل مدخلاتها.",
    "perms.chainBroken": "السلسلة غير متحققة.",
    "perms.chainCaveat": "يكشف هذا التعديل لا الاقتطاع. من يحذف من النهاية ويحرّك الرأس يترك سلسلة تتحقق، لأن كل قيمة تقارنها الفحوص موجودة في القاعدة نفسها. إغلاق ذلك يحتاج نشر تجزئة الرأس في مكان لا تصله القاعدة، ولا يوجد مكان كهذا في هذه النسخة.",
    "perms.sequence": "المُدخَل",
    "perms.category": "الفئة",
    "perms.action": "الإجراء",
    "perms.outcome": "النتيجة",
