    "stepUp.tooMany": "محاولات كثيرة. حاول بعد قليل.",
    "stepUp.unreachable": "يحتاج هذا الإجراء مفتاح أمان عتادياً لا تستطيع هذه النسخة التحقق منه. لا يستطيع أحد فعله هنا.",
