    "members.whySearch": "\u0627\u0644\u0641\u0642\u0631\u0629 4218 \u062a\u0636\u0639 \u0641\u0647\u0631\u0633 \u0628\u062d\u062b \u0648\u0627\u0639\u064a\u0627\u064b \u0644\u0644\u0635\u0644\u0627\u062d\u064a\u0627\u062a \u0645\u0639 \u062a\u0635\u0641\u064a\u0629 \u0645\u0633\u0628\u0642\u0629 \u0625\u0644\u0632\u0627\u0645\u064a\u0629 \u0641\u064a ENG-01\u060c \u0648\u0647\u064a \u063a\u064a\u0631 \u0645\u0628\u0646\u064a\u0629. \u0645\u0633\u062d LIKE \u064a\u064f\u0639\u0631\u0636 \u0643\u0628\u062d\u062b \u0647\u0648 \u0645\u0633\u0627\u0631 \u0642\u0631\u0627\u0621\u0629 \u0628\u0644\u0627 \u0639\u0642\u062f \u062d\u062f\u0627\u062b\u0629 \u0648\u0628\u0644\u0627 \u062a\u0635\u0641\u064a\u0629 \u0645\u0633\u0628\u0642\u0629.",
    "members.whyQuickFilters": "\u00ab\u0639\u0644\u064a\u0647 \u0645\u0633\u062a\u062d\u0642\u00bb \u0648\u00ab\u0645\u0646\u062a\u0647\u064d\u00bb \u0648\u00ab\u0644\u0645 \u064a\u0632\u0631 \u0645\u0646\u0630 30 \u064a\u0648\u0645\u0627\u064b\u00bb \u0643\u0644\u0651 \u0645\u0646\u0647\u0627 \u064a\u064f\u062d\u0633\u0628 \u0641\u0648\u0642 \u0628\u064a\u0627\u0646\u0627\u062a \u0648\u062d\u062f\u0629 \u0623\u062e\u0631\u0649\u061b \u0648\u062a\u0635\u0641\u064a\u0629 \u0639\u0644\u0649 \u0627\u0644\u062e\u0627\u062f\u0645 \u0639\u0628\u0631 \u0627\u0644\u0648\u062d\u062f\u0627\u062a \u0647\u064a \u0627\u0644\u0631\u0628\u0637 \u0627\u0644\u0630\u064a \u062a\u0645\u0646\u0639\u0647 \u0627\u0644\u0641\u0642\u0631\u0629 1300.",
    "members.whySavedViews": "\u0627\u0644\u0639\u0631\u0636 \u0627\u0644\u0645\u062d\u0641\u0648\u0638 \u0647\u0648 \u0645\u0631\u0634\u0651\u062d\u0627\u062a \u0648\u0623\u0639\u0645\u062f\u0629 \u0648\u062a\u0631\u062a\u064a\u0628 \u0628\u0627\u0633\u0645 \u2014 \u0648\u0644\u0627 \u0634\u064a\u0621 \u064a\u062e\u0632\u0651\u0646 \u0648\u0627\u062d\u062f\u0627\u064b.",
    "members.whyBulkActions": "\u0625\u0631\u0633\u0627\u0644 \u0631\u0633\u0627\u0644\u0629\u060c \u0625\u0631\u0633\u0627\u0644 \u0631\u0648\u0627\u0628\u0637 \u062f\u0641\u0639\u060c \u0648\u0627\u0644\u0625\u0636\u0627\u0641\u0629 \u0625\u0644\u0649 \u0634\u0631\u064a\u062d\u0629: \u0644\u0627 \u0634\u064a\u0621 \u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u0628\u0646\u0627\u0621 \u064a\u0631\u0633\u0644 \u0631\u0633\u0627\u0644\u0629\u060c \u0648\u0644\u0627 \u064a\u0648\u062c\u062f \u0631\u0627\u0628\u0637 \u062f\u0641\u0639\u060c \u0648\u0627\u0644\u0634\u0631\u0627\u0626\u062d \u0647\u064a \u0627\u0644\u0646\u0635\u0641 \u063a\u064a\u0631 \u0627\u0644\u0645\u0628\u0646\u064a \u0645\u0646 PPL-01-R05.",
    "members.whyExport": "\u0644\u0627 \u064a\u0648\u062c\u062f \u0645\u0633\u0627\u0631 \u062a\u0635\u062f\u064a\u0631\u060c \u0648\u0627\u0644\u062a\u0635\u0645\u064a\u0645 \u064a\u0636\u0639 \u0647\u0630\u0627 \u062e\u0644\u0641 \u0645\u0648\u0627\u0641\u0642\u0629.",
