    "people.lead": "لا يوجد بحث. يضع PPL-01 فهرساً يراعي الصلاحيات مع تصفية مُسبقة إلزامية في ENG-01 وهو غير مبني — ومسحٌ يُقدَّم كبحث هو مسار قراءة بلا تصفية مسبقة. قائمة التكرارات أدناه هي الموضع الوحيد الذي تجد فيه هذه الوحدة الأشخاص بقيمة.",
