    "member.credentialNote": "تُخزَّن بيانات الاعتماد كبصمة SHA-256 ولا تُقرأ مرة أخرى، فلا يوجد رقم بطاقة ولا آخر أربعة أرقام هنا — فقط النوع والحالة والنافذة. وأمّا هل يُسمح لهذا الشخص بالدخول فيُقرَّر عند كل تقديم مقابل سياسة المنطقة وعضويته واستحقاقه.",
