    "nav.integrations": "التكاملات",
    "integrations.title": "التكاملات",
    "integrations.lead": "ما هو مثبّت، وما الذي يجوز له الوصول إليه نيابةً عنك، وما أبلغ أنه فعله. بيانات الاعتماد هنا إشارة إلى خزنة لا يملكها هذا البناء، وأرقام التشغيل هي ما قاله أحدهم إنه حدث.",
    "integrations.nothingSyncs": "لا تتم أي مزامنة في هذا البناء. لا مزوّد ولا طلب خارجي ولا شيفرة مُحوِّل: يُفتح التشغيل ويُسوّى بما سيتولى العمل، ولا شيء يتولاه. أعداد السجلات أدناه ما أبلغ عنه المُستدعي، لا بيانات شوهدت وهي تنتقل.",
