    "reports.title": "\u0627\u0644\u062a\u0642\u0627\u0631\u064a\u0631",
    "reports.heading": "\u0627\u0644\u062a\u0642\u0627\u0631\u064a\u0631\u060c \u0648\u0627\u0644\u0628\u0648\u0627\u0628\u0629 \u0623\u0645\u0627\u0645 \u0627\u0644\u062a\u0635\u062f\u064a\u0631",
    "reports.lead": "\u064a\u064f\u062f\u0631\u062c \u0643\u0644 \u062a\u0642\u0631\u064a\u0631 \u0639\u0646\u062f\u0645\u0627 \u062a\u0633\u062a\u0637\u064a\u0639 \u0647\u0630\u0647 \u0627\u0644\u062c\u0644\u0633\u0629 \u0641\u062a\u062d\u0647. \u0627\u0644\u062a\u0642\u0631\u064a\u0631 \u0627\u0644\u0630\u064a \u0644\u0627 \u064a\u0645\u0643\u0646\u0643 \u0641\u062a\u062d\u0647 \u063a\u0627\u0626\u0628 \u0648\u0644\u064a\u0633 \u0645\u0642\u0641\u0644\u0627\u064b\u060c \u0644\u0623\u0646 \u0627\u0644\u0635\u0641 \u0627\u0644\u0645\u064f\u0639\u0637\u0651\u0644 \u0648\u0639\u062f \u0628\u0625\u0645\u0643\u0627\u0646\u064a\u0629 \u0641\u062a\u062d\u0647.",
    "reports.rolesLabel": "\u0627\u0644\u0623\u062f\u0648\u0627\u0631",
    "reports.gateUnreachable": "\u0644\u0645 \u062a\u0633\u062a\u062c\u0628 \u062e\u062f\u0645\u0629 \u0627\u0644\u0635\u0644\u0627\u062d\u064a\u0627\u062a\u060c \u0641\u0644\u0627 \u062a\u0633\u062a\u0637\u064a\u0639 \u0647\u0630\u0647 \u0627\u0644\u0635\u0641\u062d\u0629 \u0623\u0646 \u062a\u0642\u0648\u0644 \u0623\u064a \u0627\u0644\u062a\u0642\u0627\u0631\u064a\u0631 \u064a\u0645\u0643\u0646\u0643 \u0641\u062a\u062d\u0647\u0627. \u0647\u0630\u0627 \u062e\u0644\u0644 \u0647\u0646\u0627 \u0648\u0644\u064a\u0633 \u062d\u062f\u0651\u0627\u064b \u0639\u0644\u0649 \u0635\u0644\u0627\u062d\u064a\u0627\u062a\u0643 \u2014 \u0623\u0639\u062f \u0627\u0644\u0645\u062d\u0627\u0648\u0644\u0629.",
    "reports.noneOpen": "\u0644\u0627 \u064a\u0648\u062c\u062f \u062a\u0642\u0631\u064a\u0631 \u0647\u0646\u0627 \u0645\u062a\u0627\u062d \u0644\u0647\u0630\u0647 \u0627\u0644\u062c\u0644\u0633\u0629. \u0647\u0630\u0627 \u064a\u062e\u0635\u0651 \u0635\u0644\u0627\u062d\u064a\u0627\u062a\u0643 \u2014 \u0648\u0627\u0644\u0642\u0633\u0645 \u0623\u062f\u0646\u0627\u0647 \u064a\u062e\u0635\u0651 \u0645\u0627 \u0644\u0627 \u064a\u0633\u062a\u0637\u064a\u0639 \u0647\u0630\u0627 \u0627\u0644\u0628\u0646\u0627\u0621 \u062a\u0642\u0631\u064a\u0631\u0647 \u0625\u0637\u0644\u0627\u0642\u0627\u064b.",
    "reports.revenueName": "\u0627\u0644\u0625\u064a\u0631\u0627\u062f\u0627\u062a",
    "reports.revenueSummary": "\u0627\u0644\u0645\u062d\u0635\u0651\u0644 \u0648\u0627\u0644\u0645\u0641\u0648\u062a\u0631 \u0648\u0627\u0644\u0645\u0633\u062a\u062d\u0642\u060c \u062d\u0633\u0628 \u0627\u0644\u0645\u0635\u062f\u0631 \u0648\u0627\u0644\u0643\u064a\u0627\u0646 \u0627\u0644\u0642\u0627\u0646\u0648\u0646\u064a",
