    "reports.membershipSummary": "\u0627\u0644\u0627\u0646\u0636\u0645\u0627\u0645 \u0648\u0627\u0644\u0645\u063a\u0627\u062f\u0631\u0629 \u0648\u0635\u0627\u0641\u064a \u0627\u0644\u062d\u0631\u0643\u0629 \u0647\u0630\u0627 \u0627\u0644\u0634\u0647\u0631",
