    "attendanceReport.nobodyCameAtAll": "\u0644\u0645 \u064a\u064f\u0633\u062c\u0651\u0644 \u0623\u064a \u062f\u062e\u0648\u0644 \u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u0646\u0627\u062f\u064a \u0641\u064a \u0647\u0630\u0647 \u0627\u0644\u0623\u064a\u0627\u0645. \u0647\u0630\u0627 \u0646\u0627\u062f\u064d \u0645\u063a\u0644\u0642 \u0623\u0648 \u0642\u0627\u0631\u0626 \u063a\u064a\u0631 \u0645\u0648\u0635\u0648\u0644 \u0628\u0634\u064a\u0621\u060c \u0648\u0644\u064a\u0633 \u0646\u0627\u062f\u064a\u0627\u064b \u0647\u0627\u062f\u0626\u0627\u064b\u060c \u0648\u0644\u0647\u0630\u0627 \u0644\u0627 \u062a\u064f\u062d\u062f\u062f \u0623\u064a \u0633\u0627\u0639\u0629 \u0643\u0623\u0647\u062f\u0623 \u0633\u0627\u0639\u0629.",
    "attendanceReport.conclusion": "**{from}\u2013{to} \u0647\u064a \u0623\u0643\u062b\u0631 \u0627\u0644\u0641\u062a\u0631\u0627\u062a \u0627\u0632\u062f\u062d\u0627\u0645\u0627\u064b\u060c \u0628\u0640 {peak} \u062f\u062e\u0648\u0644 \u0641\u064a \u0623\u0643\u062b\u0631 \u0633\u0627\u0639\u0627\u062a\u0647\u0627 \u0627\u0632\u062f\u062d\u0627\u0645\u0627\u064b.** \u0648\u0627\u0644\u0633\u0627\u0639\u0629 {quiet} \u0647\u064a \u0623\u0647\u062f\u0623 \u0633\u0627\u0639\u0629 \u064a\u062f\u062e\u0644 \u0641\u064a\u0647\u0627 \u0623\u062d\u062f\u060c \u0639\u0646\u062f {percent}% \u0645\u0646 \u0627\u0644\u0630\u0631\u0648\u0629.",
