    "revenue.noComparison": "\u0644\u0627 \u064a\u0648\u062c\u062f \u0631\u0642\u0645 \u0644\u0644\u0646\u0642\u0637\u0629 \u0646\u0641\u0633\u0647\u0627 \u0645\u0646 \u0627\u0644\u0634\u0647\u0631 \u0627\u0644\u0645\u0627\u0636\u064a",
    "revenue.positionNote": "\u0627\u0644\u0645\u0633\u062a\u062d\u0642 \u0647\u0648 \u0645\u0627 \u062a\u0632\u0627\u0644 \u0641\u0648\u0627\u062a\u064a\u0631 \u0647\u0630\u0627 \u0627\u0644\u0634\u0647\u0631 \u0645\u062f\u064a\u0646\u0629 \u0628\u0647 \u0627\u0644\u0622\u0646\u060c \u0648\u0644\u0630\u0644\u0643 \u0644\u0627 \u064a\u062d\u0645\u0644 \u0645\u0642\u0627\u0631\u0646\u0629: \u0627\u0644\u0631\u0642\u0645 \u0627\u0644\u0645\u0642\u0627\u0628\u0644 \u0647\u0648 \u0631\u0635\u064a\u062f \u0643\u0645\u0627 \u0643\u0627\u0646 \u0642\u0628\u0644 \u0634\u0647\u0631\u060c \u0648\u0647\u0630\u0647 \u0627\u0644\u0642\u0631\u0627\u0621\u0629 \u0644\u0627 \u062a\u0639\u064a\u062f \u0628\u0646\u0627\u0621\u0647.",
    "revenue.separateFacts": "\u0627\u0644\u0645\u062d\u0635\u0651\u0644 \u0648\u0627\u0644\u0645\u0641\u0648\u062a\u0631 \u0639\u0645\u0648\u062f\u0627\u0646 \u0645\u0646\u0641\u0635\u0644\u0627\u0646 \u0644\u0623\u0646\u0647\u0645\u0627 \u062d\u0642\u064a\u0642\u062a\u0627\u0646 \u0645\u0646\u0641\u0635\u0644\u062a\u0627\u0646. \u0627\u0644\u062a\u0642\u0631\u064a\u0631 \u0627\u0644\u0630\u064a \u064a\u0638\u0647\u0631 \u0631\u0642\u0645\u0627\u064b \u0648\u0627\u062d\u062f\u0627\u064b \u0627\u0633\u0645\u0647 \u00ab\u0627\u0644\u0625\u064a\u0631\u0627\u062f\u00bb \u0647\u0648 \u0633\u0628\u0628 \u0639\u062c\u0632 \u0627\u0644\u0645\u0634\u063a\u0651\u0644\u064a\u0646 \u0639\u0646 \u0645\u0637\u0627\u0628\u0642\u0629 \u062f\u0641\u0627\u062a\u0631\u0647\u0645.",
    "revenue.bySource": "\u062d\u0633\u0628 \u0627\u0644\u0645\u0635\u062f\u0631",
    "revenue.sourcesAreNet": "\u0635\u0641 \u0627\u0644\u0645\u0635\u062f\u0631 \u0635\u0627\u0641\u064d \u0645\u0646 \u0627\u0644\u0636\u0631\u064a\u0628\u0629\u060c \u0648\u0631\u0642\u0645 \u0627\u0644\u0645\u0641\u0648\u062a\u0631 \u0623\u0639\u0644\u0627\u0647 \u0625\u062c\u0645\u0627\u0644\u064a. \u0627\u0644\u0636\u0631\u064a\u0628\u0629 \u062a\u064f\u062d\u0635\u0651\u0644 \u0646\u064a\u0627\u0628\u0629 \u0639\u0646 \u062c\u0647\u0629 \u0623\u062e\u0631\u0649 \u0648\u0644\u064a\u0633\u062a \u0625\u064a\u0631\u0627\u062f\u0627\u064b\u060c \u0641\u0627\u0644\u062a\u0641\u0635\u064a\u0644 \u0635\u0627\u0641\u064d \u0648\u0635\u0641 \u0627\u0644\u0645\u062c\u0645\u0648\u0639 \u0647\u0648 \u0627\u0644\u0631\u0642\u0645 \u0627\u0644\u0630\u064a \u064a\u062c\u0645\u0639 \u0625\u0644\u064a\u0647.",
