    "membershipReport.whyTitle": "\u0644\u0645\u0627\u0630\u0627 \u063a\u0627\u062f\u0631\u0648\u0627",
    "membershipReport.whyUnavailable": "\u064a\u0633\u062c\u0651\u0644 \u0627\u0644\u0625\u0644\u063a\u0627\u0621 \u0633\u0628\u0628\u0647 \u0646\u0635\u0627\u064b \u062d\u0631\u0627\u064b \u0644\u0627 \u0633\u0628\u0628\u0627\u064b \u0645\u0631\u0645\u0651\u0632\u0627\u064b\u060c \u0641\u0644\u0627 \u0634\u064a\u0621 \u064a\u064f\u0639\u062f\u0651. \u064a\u0631\u0633\u0645 \u0627\u0644\u062a\u0635\u0645\u064a\u0645 \u062e\u0645\u0633\u0629 \u0623\u0633\u0628\u0627\u0628 \u0645\u0633\u0645\u0651\u0627\u0629 \u0645\u0646 \u062d\u0642\u0644 \u0625\u0644\u0632\u0627\u0645\u064a\u061b \u0648\u0625\u0646\u062a\u0627\u062c\u0647\u0627 \u0645\u0646 \u0646\u0635 \u062d\u0631\u0651 \u064a\u0639\u0646\u064a \u062a\u0635\u0646\u064a\u0641 \u0645\u0627 \u0643\u062a\u0628\u0647 \u0634\u062e\u0635\u060c \u0648\u062a\u0642\u0631\u064a\u0631 \u0627\u0644\u0627\u062d\u062a\u0641\u0627\u0638 \u0644\u064a\u0633 \u0645\u0643\u0627\u0646 \u0627\u0644\u062a\u062e\u0645\u064a\u0646.",
    "membershipReport.whyAlsoSensitive": "\u0627\u0644\u0646\u0635 \u0646\u0641\u0633\u0647 \u0644\u0627 \u064a\u064f\u0639\u0631\u0636 \u0647\u0646\u0627 \u0623\u064a\u0636\u0627\u064b. \u062d\u0642\u0644 \u0627\u0644\u0633\u0628\u0628 \u0647\u0648 \u062d\u064a\u062b \u062a\u0646\u062a\u0647\u064a \u0627\u0644\u062d\u0642\u064a\u0642\u0629 \u0627\u0644\u0635\u062d\u064a\u0629 \u0639\u0645\u0644\u064a\u0627\u064b\u060c \u0648\u0647\u0630\u0627 \u0627\u0644\u062a\u0642\u0631\u064a\u0631 \u062e\u0644\u0641 \u0635\u0644\u0627\u062d\u064a\u0629 \u0631\u0648\u062a\u064a\u0646\u064a\u0629 \u0639\u0644\u0649 \u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0645\u0633\u062a\u0623\u062c\u0631.",
    "membershipReport.cohortTitle": "\u0627\u0644\u0627\u062d\u062a\u0641\u0627\u0638 \u062d\u0633\u0628 \u0627\u0644\u0641\u0648\u062c \u063a\u064a\u0631 \u0645\u0628\u0646\u064a",
    "membershipReport.cohortWhy": "\u0627\u0644\u0627\u062d\u062a\u0641\u0627\u0638 \u062d\u0633\u0628 \u0641\u0648\u062c \u0627\u0644\u0627\u0646\u0636\u0645\u0627\u0645 \u064a\u062d\u062a\u0627\u062c \u0645\u062a\u0627\u0628\u0639\u0629 \u0628\u062f\u0627\u064a\u0629 \u0648\u0646\u0647\u0627\u064a\u0629 \u0643\u0644 \u0639\u0636\u0648\u064a\u0629 \u0634\u0647\u0631\u0627\u064b \u0628\u0634\u0647\u0631. \u0633\u062c\u0644 \u062f\u0648\u0631\u0629 \u0627\u0644\u062d\u064a\u0627\u0629 \u064a\u0633\u062a\u0637\u064a\u0639 \u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0648\u0644\u0627 \u0634\u064a\u0621 \u064a\u0641\u0639\u0644 \u0630\u0644\u0643 \u0628\u0639\u062f.",
    "membershipReport.refusedWhy": "\u064a\u062d\u062a\u0627\u062c \u0647\u0630\u0627 \u0627\u0644\u062a\u0642\u0631\u064a\u0631 \u0625\u0644\u0649 membership.record.read.",
    "wallet.title": "\u0627\u0644\u0645\u062d\u0641\u0638\u0629 \u0648\u0627\u0644\u0623\u0631\u0635\u062f\u0629",
