    "wallet.refundableWhy": "\u0627\u0644\u0646\u0642\u062f \u0627\u0644\u0630\u064a \u062f\u0641\u0639\u0648\u0647. \u0627\u0644\u0642\u064a\u0645\u0629 \u0627\u0644\u062a\u0631\u0648\u064a\u062c\u064a\u0629 \u062a\u064f\u0646\u0641\u0642 \u0648\u0644\u0627 \u062a\u064f\u0633\u062a\u0631\u062f \u0623\u0628\u062f\u0627\u064b\u060c \u0648\u0644\u0630\u0644\u0643 \u062a\u064f\u062d\u0633\u0628\u0627\u0646 \u0645\u0646\u0641\u0635\u0644\u062a\u064a\u0646.",
