    "staff.srUnreachable": "ممنوحة وغير قابلة للاستخدام",
    "staff.grants.whyNoUnticked": "**لا صفوف غير مؤشَّرة، وهذا رفضٌ لا إغفال.** يرسم التصميم قدرتين لا يحملهما هذا الشخص، وهو ما يفترض مجموعة معروفة يُقاس عليها أحد. ولا توجد هنا: الصلاحية موجودة إن حملها دور، وكل دور ملك المستأجر، و«ما يمكن أن يحمله أحد» هو الفهرس كاملاً. واختيار اثنتين منها كالغيابين المهمّين اختراعٌ لفكرة المنتج نفسه عن القدرة الخطيرة.",
    "staff.aal3Unreachable": "الصلاحية الموسومة غير قابلة للاستخدام تحتاج مستوى توكيد 3، وهو يحتاج مُوثِّقاً عتادياً لا يستطيع هذا البناء التحقّق منه. فهي ممنوحة ومسجَّلة ولا يستطيع أحد استخدامها — ورسمها كمتوفّرة يقول إن أحداً يستطيع ما لا تستطيعه أي جلسة.",
    "staff.tierFour": "تغيير أي من هذا يحتاج دخولاً أقوى، وهو مسجَّل: منح دور أو إلغاؤه صلاحية من الصنف الماليّ، والفعل يُكتب في سجلّ التدقيق المتسلسل بالبصمات مسمّياً الشخصين.",
