    "dispute.strongestEvidence": "**سجلّ الدخول أقوى دليل يملكه النادي**، وهو السطر الوحيد هنا الذي يجمعه فيرو لا يقتبسه: يُحسب من دخول الأبواب لا من قرارات الدخول، لأن بطاقةً تتعثّر عند الباب تُنتج قرارات رفض للعضو نفسه الذي يُراد إثبات حضوره. وتُؤرَّخ كل زيارة بتوقيت النادي الذي دخل منه، وهذا ما تعنيه «الفترة المفوترة» لمن يقرأ الملف.",
