    "dispute.submitWhy": "لا شيء في هذا البناء يرسل شيئاً إلى شبكة. يسجّل `respond_to_dispute` أن فاعلاً مُسمّى أرسل أدلة، ويأخذ مُحدِّد موقع لا الأدلة نفسها — فصفٌّ يقول إن الملف أُجيب عنه، كتبه ما لم يُجب عنه، هو شكل الأدلة المُلفَّقة الذي لُدغت به هذه الشيفرة. وهي كتابة ماليّة مُصعَّدة بلا نموذج هنا.",
